import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

// supabase/functions/mcp/index.ts is generated by the Lovable plugin (@lovable.dev/mcp-js) from src/lib/mcp
// and everything it imports (src/content/*). The plugin cannot stamp a hash into it, so this test bundles the
// same entry with the plugin's own esbuild options (scripts/mcp-bundle-from-sources.mjs) and compares the
// result with the committed file. A red test means Lovable must regenerate the bundle.
// Never edit, replace or regenerate the bundle to make this pass.

const ROOT = process.cwd();
const BUNDLE = "supabase/functions/mcp/index.ts";
const BANNER =
  "// AUTO-GENERATED by @lovable.dev/mcp-js — do not edit. Regenerated by the Vite plugin.\n" +
  "// To take ownership, delete this banner line; the plugin then leaves the file alone.";

const normalise = (text: string) => text.replace(/\r\n/g, "\n");
const mcpVersion: string = JSON.parse(readFileSync(resolve(ROOT, "node_modules/@lovable.dev/mcp-js/package.json"), "utf8")).version;

/** A short, actionable account of the first difference between the committed and the rebuilt bundle. */
export function describeStale(committed: string, rebuilt: string): string {
  const a = committed.split("\n");
  const b = rebuilt.split("\n");
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  return [
    `${BUNDLE} is older than its sources (the first difference is at line ${i + 1} of ${a.length}).`,
    `committed: ${(a[i] ?? "(end of file)").slice(0, 140)}`,
    `sources:   ${(b[i] ?? "(end of file)").slice(0, 140)}`,
    "Lovable must regenerate the bundle. Do not edit, replace or regenerate it yourself: report it.",
  ].join("\n");
}

describe("MCP bundle freshness", () => {
  it("describes the first difference and tells the reader to report, not fix", () => {
    const message = describeStale("a\nold line\nc", "a\nnew line\nc");
    expect(message).toContain("first difference is at line 2 of 3");
    expect(message).toContain("committed: old line");
    expect(message).toContain("sources:   new line");
    expect(message).toContain("Lovable must regenerate the bundle");
    expect(describeStale("a", "a\nb")).toContain("(end of file)");
  });

  it("is a bundle the plugin generated, with the plugin version this test copies the options from", () => {
    const committed = normalise(readFileSync(resolve(ROOT, BUNDLE), "utf8"));
    expect(committed.startsWith(BANNER), "the generated-by banner is missing: was the file replaced by hand?").toBe(true);
    expect(committed).toContain("// Bundled from src/lib/mcp/index.ts by @lovable.dev/mcp-js.");
    expect(committed, "the bundle was made by another plugin version: re-check the options copied in the script").toContain(
      `npm:@lovable.dev/mcp-js@${mcpVersion}`,
    );
    expect(committed, "this is the stub a Windows build writes, not a real bundle").not.toContain("npm:C:");
  });

  it("is what the current sources bundle to (src/lib/mcp and everything it imports)", () => {
    const committed = normalise(readFileSync(resolve(ROOT, BUNDLE), "utf8"));
    const rebuilt = normalise(
      execFileSync(process.execPath, ["scripts/mcp-bundle-from-sources.mjs"], { cwd: ROOT, maxBuffer: 1 << 26, encoding: "utf8" }),
    );
    expect(committed === rebuilt ? "" : describeStale(committed, rebuilt)).toBe("");
  });
});
